{
  "units": [
    {
      "quote_ref": "F000:F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section designation and title identifying § 1910.157 Portable fire extinguishers, which serves as an organizational heading without substantive regulatory requirements."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The requirements of § 1910.157 apply to the placement, use, maintenance, and testing of portable fire extinguishers provided for the use of employees."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "Paragraph (d) of § 1910.157 does not apply to extinguishers provided for employee use on the outside of workplace buildings or structures."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "Where extinguishers are provided in the workplace but are not intended for employee use, and the employer has an emergency action plan and a fire prevention plan meeting the requirements of 29 CFR 1910.38 and 29 CFR 1910.39 respectively, then only the requirements of paragraphs (e) and (f) of § 1910.157 apply."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph (b) heading 'Exemptions', providing organizational structure without substantive content."
    },
    {
      "quote_ref": "F004:F005",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "Where an employer has established and implemented a written fire safety policy requiring immediate and total evacuation of employees from the workplace upon the sounding of a fire alarm signal, including an emergency action plan and fire prevention plan meeting 29 CFR 1910.38 and 29 CFR 1910.39 respectively, and extinguishers are not available in the workplace, the employer is exempt from all requirements of § 1910.157, unless a specific standard in part 1910 requires that a portable fire extinguisher be provided."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "Where the employer has an emergency action plan meeting the requirements of § 1910.38 that designates certain employees as the only employees authorized to use available portable fire extinguishers and requires all other employees in the fire area to immediately evacuate the affected work area upon the sounding of the fire alarm, the employer is exempt from the distribution requirements in paragraph (d) of § 1910.157."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph (c) heading 'General requirements', providing organizational structure without substantive content."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall provide portable fire extinguishers and shall mount, locate, and identify them so that they are readily accessible to employees without subjecting the employees to possible injury."
    },
    {
      "quote_ref": "F009",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Only approved portable fire extinguishers shall be used to meet the requirements of § 1910.157."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "The employer shall not provide or make available in the workplace portable fire extinguishers using carbon tetrachloride or chlorobromomethane extinguishing agents."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall assure that portable fire extinguishers are maintained in a fully charged and operable condition and kept in their designated places at all times except during use."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall remove from service all soldered or riveted shell self-generating soda acid or self-generating foam or gas cartridge water type portable fire extinguishers that are operated by inverting the extinguisher to rupture the cartridge or to initiate an uncontrollable pressure-generating chemical reaction to expel the agent."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph (d) heading 'Selection and distribution', providing organizational structure without substantive content."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Portable fire extinguishers shall be provided for employee use and selected and distributed based on the classes of anticipated workplace fires and on the size and degree of hazard that would affect their use."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall distribute portable fire extinguishers for use by employees on Class A fires so that the travel distance for employees to any extinguisher is 75 feet (22.9 m) or less."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "alternative",
      "meaning": "The employer may use uniformly spaced standpipe systems or hose stations connected to a sprinkler system installed for emergency use by employees instead of Class A portable fire extinguishers, provided that such systems meet the respective requirements of § 1910.158 or § 1910.159, provide total coverage of the area to be protected, and employees are trained at least annually in their use."
    },
    {
      "quote_ref": "F017",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall distribute portable fire extinguishers for use by employees on Class B fires so that the travel distance from the Class B hazard area to any extinguisher is 50 feet (15.2 m) or less."
    },
    {
      "quote_ref": "F018",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall distribute portable fire extinguishers used for Class C hazards on the basis of the appropriate pattern for the existing Class A or Class B hazards."
    },
    {
      "quote_ref": "F019",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall distribute portable fire extinguishers or other containers of Class D extinguishing agent for use by employees so that the travel distance from the combustible metal working area to any extinguishing agent is 75 feet (22.9 m) or less."
    },
    {
      "quote_ref": "F019",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Portable fire extinguishers for Class D hazards are required in combustible metal working areas where combustible metal powders, flakes, shavings, or similarly sized products are generated at least once every two weeks."
    }
  ]
}
